import std/[base64, httpclient, json, os, strutils]

let apiKey = getEnv("FLYMYAI_API_KEY", "fly-***")
let apiUrl = getEnv("FLYMYAI_API_URL", "")
let model = "flymyai/bytedance-seedream-5_0_pro"

if apiKey == "fly-***" or apiKey.len == 0:
  raise newException(ValueError, "Set FLYMYAI_API_KEY to a valid FlyMyAI API key")

let payload = %*{
  "model": model,
  "payload": {
    "prompt": "At breakneck speed, drones thread through intricate obstacles or stunning natural wonders, delivering an immersive, heart-pounding flying experience.",
    "size": "2k",
    "watermark": false,
    "sequential_image_generation": "disabled",
    "optimize_prompt_mode": "standard"
  }
}

let headers = newHttpHeaders({
  "Authorization": "Bearer " & apiKey,
  "Content-Type": "application/json",
  "Accept": "application/json"
})

proc extractImageData(responseJson: JsonNode): string =
  let outputData = responseJson{"output_data"}

  if outputData.isNil:
    raise newException(ValueError, "Response does not contain output_data")

  for key in ["image", "sample", "output"]:
    let value = outputData{key}

    if value.isNil:
      continue

    case value.kind
    of JString:
      return value.getStr
    of JArray:
      if value.len > 0 and value[0].kind == JString:
        return value[0].getStr
    else:
      discard

  raise newException(ValueError, "Response does not contain a supported image output")

var client = newHttpClient()
client.headers = headers

try:
  let response = client.request(
    apiUrl,
    httpMethod = HttpPost,
    body = $payload
  )

  defer:
    response.close()

  let responseBody = response.body

  if response.code.int < 200 or response.code.int >= 300:
    raise newException(
      IOError,
      "FlyMyAI prediction failed with HTTP " & $response.code & ": " & responseBody
    )

  let responseJson = parseJson(responseBody)
  var imageEncoded = extractImageData(responseJson)

  if imageEncoded.startsWith("data:"):
    let commaIndex = imageEncoded.find(',')

    if commaIndex < 0:
      raise newException(ValueError, "Invalid data URI image output")

    imageEncoded = imageEncoded[commaIndex + 1 .. ^1]

  let imageData = decode(imageEncoded)
  writeFile("image_output.jpg", imageData)
  echo "Saved image_output.jpg"
finally:
  client.close()
